// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {Script, console} from "forge-std/Script.sol";
import {MyFlashLoanReceiver} from "../src/MyFlashLoanReceiver.sol";

/// @notice Generated by HARNESS. Deploys MyFlashLoanReceiver against Aave v3 on Ethereum.
contract DeployMyFlashLoanReceiver is Script {
    address constant POOL_ADDRESSES_PROVIDER = 0x2f39d218133AFaB8F2B819B1066c7E434Ad94E9e;
    address constant ASSET = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;

    function run() external {
        uint256 pk = vm.envUint("PRIVATE_KEY");
        address deployer = vm.addr(pk);

        vm.startBroadcast(pk);
        MyFlashLoanReceiver deployed = new MyFlashLoanReceiver(POOL_ADDRESSES_PROVIDER, ASSET, deployer);
        vm.stopBroadcast();

        console.log("MyFlashLoanReceiver deployed at", address(deployed));
    }
}
